import sys
import sqlite3
import xml.etree.ElementTree as ET
import csv
import re
from decimal import Decimal

def parse_expression(expr, row):
    # Replace column names with their values from the row
    for col in row.keys():
        expr = expr.replace(col, str(row[col]))
    # Evaluate the expression safely
    try:
        return eval(expr, {'__builtins__': None}, {})
    except:
        return None

def process_filters(filters, row):
    for filter_elem in filters:
        col = filter_elem.get('column')
        op = filter_elem.get('op')
        value = filter_elem.get('value')
        if col not in row:
            return False
        row_val = row[col]
        if op == '=':
            if row_val != value:
                return False
        elif op == '!=':
            if row_val == value:
                return False
        elif op == '<':
            if row_val >= value:
                return False
        elif op == '<=':
            if row_val > value:
                return False
        elif op == '>':
            if row_val <= value:
                return False
        elif op == '>=':
            if row_val < value:
                return False
    return True

def main():
    if len(sys.argv) != 3:
        print("Usage: python report.py <config.xml> <database.sqlite3>")
        sys.exit(1)

    config_xml = sys.argv[1]
    db_file = sys.argv[2]

    try:
        tree = ET.parse(config_xml)
        root = tree.getroot()
    except ET.ParseError as e:
        print(f"Error parsing XML: {e}")
        sys.exit(1)

    table_name = root.get('table')
    if not table_name:
        print("Error: table attribute is required in <report>")
        sys.exit(1)

    columns_elem = root.find('columns')
    filters_elem = root.find('filters')
    order_elem = root.find('order')
    limit_elem = root.find('limit')

    columns = []
    for col_elem in columns_elem.findall('column'):
        name = col_elem.get('name')
        source = col_elem.get('source')
        columns.append((name, source))

    filters = []
    if filters_elem is not None:
        for filter_elem in filters_elem.findall('filter'):
            filters.append(filter_elem)

    order_by = None
    order_direction = None
    if order_elem is not None:
        order_by = order_elem.get('by')
        order_direction = order_elem.get('direction').lower()

    limit_value = None
    if limit_elem is not None:
        try:
            limit_value = int(limit_elem.get('value'))
        except ValueError:
            print("Error: limit value must be an integer")
            sys.exit(1)

    conn = sqlite3.connect(db_file)
    cursor = conn.cursor()
    cursor.execute(f"SELECT * FROM {table_name}")
    rows = cursor.fetchall()

    # Get column names from the database
    cursor.execute(f"PRAGMA table_info({table_name})")
    db_columns = [col[1] for col in cursor.fetchall()]

    processed_rows = []
    for row in rows:
        row_dict = dict(zip(db_columns, row))
        if filters and not process_filters(filters, row_dict):
            continue

        computed_values = []
        for name, source in columns:
            if source in db_columns:
                computed_values.append(row_dict[source])
            else:
                try:
                    computed_value = parse_expression(source, row_dict)
                    if computed_value is None:
                        computed_values.append(None)
                    else:
                        computed_values.append(computed_value)
                except:
                    computed_values.append(None)

        processed_rows.append((row_dict, computed_values))

    # Apply order and limit
    if order_by and order_direction:
        processed_rows.sort(key=lambda x: x[0].get(order_by, ''), reverse=(order_direction == 'desc'))

    if limit_value is not None:
        processed_rows = processed_rows[:limit_value]

    # Prepare CSV output
    output = []
    header = [col[0] for col in columns]
    output.append(header)

    for row_dict, computed_values in processed_rows:
        row = []
        for i, (name, _) in enumerate(columns):
            val = computed_values[i]
            if val is None:
                row.append('')
            else:
                # Handle CSV escaping
                if isinstance(val, str) and (',' in val or '"' in val or '\n' in val):
                    row.append(f'"{val.replace('"', '""')}"')
                else:
                    row.append(str(val))
        output.append(row)

    # Write CSV
    writer = csv.writer(sys.stdout)
    writer.writerows(output)

    conn.close()

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import sqlite3
import re
from decimal import Decimal

def parse_xml(xml_file):
    tree = ET.parse(xml_file)
    root = tree.getroot()
    return root

def parse_config(config_xml):
    root = parse_xml(config_xml)
    report = root.find('report')
    table = report.attrib['table']
    columns = []
    for col in report.findall('column'):
        name = col.attrib['name']
        source = col.attrib['source']
        columns.append({'name': name, 'source': source})
    filter_ = root.find('filter')
    filter_column = filter_.attrib['column'] if filter_ is not None else None
    filter_value = filter_.attrib['value'] if filter_ is not None else None
    order = root.find('order')
    order_by = order.attrib['by'] if order is not None else None
    order_direction = order.attrib['direction'] if order is not None else None
    limit = root.find('limit')
    limit_value = int(limit.attrib['value']) if limit is not None else None
    return table, columns, filter_column, filter_value, order_by, order_direction, limit_value

def evaluate_expression(row, source):
    for col in row:
        if col[0] in source:
            source = source.replace(col[0], str(row[col[0]]))
    try:
        return eval(source, {'__builtins__': None}, {})
    except:
        return None

def process_data(db_file, table, columns, filter_column, filter_value, order_by, order_direction, limit_value):
    conn = sqlite3.connect(db_file)
    cursor = conn.cursor()
    cursor.execute(f"SELECT * FROM {table}")
    rows = cursor.fetchall()
    conn.close()

    column_names = [col['name'] for col in columns]
    result_rows = []

    for row in rows:
        processed_row = {}
        for col in columns:
            name = col['name']
            source = col['source']
            if source in [col_name for col_name in row]:
                col_index = [i for i, col_name in enumerate(row) if col_name == source][0]
                processed_row[name] = row[col_index]
            else:
                computed_value = evaluate_expression(row, source)
                if computed_value is not None:
                    processed_row[name] = Decimal(str(computed_value)).quantize(Decimal('0.00'))
                else:
                    processed_row[name] = None
        result_rows.append(processed_row)

    if filter_column and filter_value:
        filtered_rows = [row for row in result_rows if row[filter_column] == filter_value]
    else:
        filtered_rows = result_rows

    if order_by and order_direction:
        reverse = (order_direction == 'desc')
        filtered_rows.sort(key=lambda x: x[order_by], reverse=reverse)

    if limit_value:
        filtered_rows = filtered_rows[:limit_value]

    return filtered_rows, column_names

def format_output(rows, column_names):
    output = []
    header = ','.join(column_names)
    output.append(header)

    for row in rows:
        formatted_row = []
        for name in column_names:
            value = row[name]
            if value is None:
                formatted_row.append('')
            else:
                str_value = str(value)
                if ',' in str_value or '"' in str_value or '\n' in str_value:
                    formatted_row.append(f'"{str_value.replace('"', '""')}"')
                else:
                    formatted_row.append(str_value)
        output.append(','.join(formatted_row))
    return '\n'.join(output)

def main():
    if len(sys.argv) != 3:
        print("Usage: python report.py config.xml data.sqlite3")
        sys.exit(1)

    config_file = sys.argv[1]
    db_file = sys.argv[2]

    table, columns, filter_column, filter_value, order_by, order_direction, limit_value = parse_config(config_file)
    rows, column_names = process_data(db_file, table, columns, filter_column, filter_value, order_by, order_direction, limit_value)
    print(format_output(rows, column_names))

if __name__ == "__main__":
    main()

