import sys
import xml.etree.ElementTree as ET
import sqlite3
import re

def parse_xml(xml_file):
    tree = ET.parse(xml_file)
    root = tree.getroot()
    columns = []
    for col in root.findall('column'):
        name = col.get('name')
        source = col.get('source')
        columns.append((name, source))
    return columns

def evaluate_expression(row, expr):
    # Replace column names with their values from the row
    for col_name in row:
        expr = re.sub(r'\b' + re.escape(col_name) + r'\b', str(row[col_name]), expr)
    # Evaluate the arithmetic expression
    try:
        return eval(expr)
    except:
        return None

def process_data(columns, db_file):
    conn = sqlite3.connect(db_file)
    cursor = conn.cursor()
    table = columns[0][1].split('"')[1] if '"' in columns[0][1] else columns[0][1].split("'")[1]
    cursor.execute(f"SELECT * FROM {table}")
    rows = cursor.fetchall()
    conn.close()

    # Get column names from the first row
    if rows:
        first_row = dict(zip([row[0] for row in cursor.description], rows[0]))
    else:
        return

    output_columns = [col[0] for col in columns]
    output = []

    for row in rows:
        processed_row = []
        for col in columns:
            name, source = col
            if source in row:
                value = row[source]
            else:
                value = evaluate_expression(row, source)
            processed_row.append(value)
        output.append(processed_row)

    return output_columns, output

def format_output(columns, rows):
    header = ','.join(columns)
    output = [header]

    for row in rows:
        formatted_row = []
        for value in row:
            if value is None:
                formatted_row.append('')
            else:
                str_val = str(value)
                if ',' in str_val or '"' in str_val or '\n' in str_val:
                    str_val = str_val.replace('"', '""')
                    formatted_row.append(f'"{str_val}"')
                else:
                    formatted_row.append(str_val)
        output.append(','.join(formatted_row))

    return '\n'.join(output)

def main():
    if len(sys.argv) != 3:
        print("Usage: python report.py config.xml data.sqlite3")
        return

    xml_file = sys.argv[1]
    db_file = sys.argv[2]

    columns = parse_xml(xml_file)
    output_columns, rows = process_data(columns, db_file)
    formatted_output = format_output(output_columns, rows)
    print(formatted_output)

if __name__ == "__main__":
    main()
